// Generates supabase/migrations/20261101000000_saas_core.sql from lib/modules.ts.
// Run: node scripts/generate-migration.ts   (Node 22.18+ strips the TypeScript types)
import { writeFileSync } from 'node:fs';
import { MODULES, type ModuleDef } from '../lib/modules.ts';
import { SQL_TYPE } from '../lib/db-types.ts';

export const MIGRATION_PATH = 'supabase/migrations/20261101000000_saas_core.sql';

const CORE = `-- ============================================================================
-- TradeQuote PRO — SaaS core schema (baseline for a NEW Supabase project)
-- Generated by scripts/generate-migration.ts from lib/modules.ts. Do not edit by hand.
--
-- Every tenant table is isolated by row level security: a signed-in user only
-- ever sees and changes rows of their own company, within their role's rights,
-- and only while the company's subscription or trial is active.
-- ============================================================================

-- Companies -------------------------------------------------------------------
create table public.companies (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 200),
  province text not null check (province in ('AB','BC','SK','MB','ON','QC','NB','NS','PE','NL','YT','NT','NU')),
  stripe_customer_id text unique,
  stripe_subscription_id text,
  subscription_status text not null default 'trialing',
  trial_ends_at timestamptz not null default (now() + interval '14 days'),
  current_period_end timestamptz,
  created_at timestamptz not null default now()
);

create table public.company_users (
  user_id uuid primary key references auth.users(id) on delete cascade,
  company_id uuid not null references public.companies(id) on delete cascade,
  role text not null check (role in ('owner','admin','project_manager','foreman','electrician')),
  full_name text,
  email text,
  created_at timestamptz not null default now()
);
create index company_users_company_idx on public.company_users(company_id);

create table public.invitations (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  email text not null check (email = lower(email) and char_length(email) <= 320),
  role text not null check (role in ('admin','project_manager','foreman','electrician')),
  -- 64 hex chars from two v4 UUIDs (built-in, cryptographically random)
  token text not null unique default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  invited_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '7 days'),
  accepted_at timestamptz
);
create index invitations_email_idx on public.invitations(email) where accepted_at is null;

create table public.ai_usage (
  company_id uuid not null references public.companies(id) on delete cascade,
  day date not null default current_date,
  messages integer not null default 0,
  primary key (company_id, day)
);

create table public.stripe_events (
  id text primary key,
  type text not null,
  created_at timestamptz not null default now()
);

-- Helpers ---------------------------------------------------------------------
create or replace function public.role_rank(r text) returns integer
language sql immutable as $$
  select case r when 'owner' then 5 when 'admin' then 4 when 'project_manager' then 3
                when 'foreman' then 2 when 'electrician' then 1 else 0 end
$$;

create or replace function public.user_company_id() returns uuid
language sql stable security definer set search_path = public as $$
  select company_id from public.company_users where user_id = auth.uid()
$$;

create or replace function public.user_rank() returns integer
language sql stable security definer set search_path = public as $$
  select coalesce((select public.role_rank(role) from public.company_users where user_id = auth.uid()), 0)
$$;

create or replace function public.company_can_write() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.companies c
    where c.id = public.user_company_id()
      and (c.subscription_status in ('active', 'past_due')
           or (c.subscription_status = 'trialing' and c.trial_ends_at > now()))
  )
$$;

create or replace function public.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  new.company_id := old.company_id;
  new.created_by := old.created_by;
  return new;
end $$;

-- Onboarding and team management (the only way rows reach company_users) ------
create or replace function public.create_company(p_name text, p_province text, p_full_name text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_company uuid;
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  if exists (select 1 from public.company_users where user_id = auth.uid()) then
    raise exception 'You already belong to a company' using errcode = '23505';
  end if;
  insert into public.companies (name, province) values (trim(p_name), upper(p_province)) returning id into v_company;
  insert into public.company_users (user_id, company_id, role, full_name, email)
    values (auth.uid(), v_company, 'owner', nullif(trim(p_full_name), ''), lower(auth.jwt() ->> 'email'));
  return v_company;
end $$;

create or replace function public.pending_invitations()
returns table (token text, company_name text, role text)
language sql stable security definer set search_path = public as $$
  select i.token, c.name, i.role
  from public.invitations i join public.companies c on c.id = i.company_id
  where i.email = lower(auth.jwt() ->> 'email') and i.accepted_at is null and i.expires_at > now()
$$;

create or replace function public.accept_invitation(p_token text, p_full_name text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_inv public.invitations%rowtype;
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_inv from public.invitations
    where token = p_token and accepted_at is null and expires_at > now()
    for update;
  if not found or v_inv.email <> lower(auth.jwt() ->> 'email') then
    raise exception 'Invitation not found or expired' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.company_users where user_id = auth.uid()) then
    raise exception 'You already belong to a company' using errcode = '23505';
  end if;
  insert into public.company_users (user_id, company_id, role, full_name, email)
    values (auth.uid(), v_inv.company_id, v_inv.role, nullif(trim(p_full_name), ''), v_inv.email);
  update public.invitations set accepted_at = now() where id = v_inv.id;
  return v_inv.company_id;
end $$;

create or replace function public.set_member_role(p_user uuid, p_role text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if public.user_rank() < 4 then raise exception 'Only owners and admins can change roles' using errcode = '42501'; end if;
  if p_user = auth.uid() then raise exception 'You cannot change your own role' using errcode = '42501'; end if;
  if p_role not in ('admin','project_manager','foreman','electrician') then raise exception 'Invalid role' using errcode = '22023'; end if;
  if p_role = 'admin' and public.user_rank() < 5 then raise exception 'Only the owner can make admins' using errcode = '42501'; end if;
  update public.company_users set role = p_role
    where user_id = p_user and company_id = public.user_company_id() and role <> 'owner'
      and (public.user_rank() = 5 or role <> 'admin');
  if not found then raise exception 'Member not found' using errcode = 'P0002'; end if;
end $$;

create or replace function public.remove_member(p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if public.user_rank() < 4 then raise exception 'Only owners and admins can remove members' using errcode = '42501'; end if;
  if p_user = auth.uid() then raise exception 'You cannot remove yourself' using errcode = '42501'; end if;
  delete from public.company_users
    where user_id = p_user and company_id = public.user_company_id() and role <> 'owner'
      and (public.user_rank() = 5 or role <> 'admin');
  if not found then raise exception 'Member not found' using errcode = 'P0002'; end if;
end $$;

-- AI assistant fair-use limit, counted per company per day.
create or replace function public.consume_ai_message()
returns table (allowed boolean, used integer, daily_limit integer)
language plpgsql security definer set search_path = public as $$
declare
  v_company uuid := public.user_company_id();
  v_limit integer;
  v_used integer;
begin
  if v_company is null then return query select false, 0, 0; return; end if;
  select case
           when c.subscription_status in ('active', 'past_due') then 400
           when c.subscription_status = 'trialing' and c.trial_ends_at > now() then 40
           else 0 end
    into v_limit from public.companies c where c.id = v_company;
  insert into public.ai_usage (company_id, day, messages) values (v_company, current_date, 0)
    on conflict (company_id, day) do nothing;
  update public.ai_usage set messages = messages + 1
    where company_id = v_company and day = current_date and messages < v_limit
    returning messages into v_used;
  if v_used is null then
    select messages into v_used from public.ai_usage where company_id = v_company and day = current_date;
    return query select false, v_used, v_limit;
  else
    return query select true, v_used, v_limit;
  end if;
end $$;

-- Core table security ---------------------------------------------------------
alter table public.companies enable row level security;
alter table public.company_users enable row level security;
alter table public.invitations enable row level security;
alter table public.ai_usage enable row level security;
alter table public.stripe_events enable row level security;

create policy companies_select on public.companies for select to authenticated
  using (id = public.user_company_id());
create policy companies_update on public.companies for update to authenticated
  using (id = public.user_company_id() and public.user_rank() = 5)
  with check (id = public.user_company_id());

create policy company_users_select on public.company_users for select to authenticated
  using (company_id = public.user_company_id());

create policy invitations_select on public.invitations for select to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 4);
create policy invitations_insert on public.invitations for insert to authenticated
  with check (company_id = public.user_company_id() and public.user_rank() >= 4
              and public.company_can_write()
              and (role <> 'admin' or public.user_rank() = 5));
create policy invitations_delete on public.invitations for delete to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 4);

create policy ai_usage_select on public.ai_usage for select to authenticated
  using (company_id = public.user_company_id());

revoke all on public.companies, public.company_users, public.invitations, public.ai_usage, public.stripe_events from anon, authenticated;
grant select on public.companies, public.company_users, public.ai_usage to authenticated;
grant update (name, province) on public.companies to authenticated;
grant select, insert, delete on public.invitations to authenticated;

revoke execute on function public.role_rank(text), public.user_company_id(), public.user_rank(),
  public.company_can_write(), public.create_company(text, text, text), public.pending_invitations(),
  public.accept_invitation(text, text), public.set_member_role(uuid, text), public.remove_member(uuid),
  public.consume_ai_message(), public.set_updated_at() from anon, public;
grant execute on function public.role_rank(text), public.user_company_id(), public.user_rank(),
  public.company_can_write(), public.create_company(text, text, text), public.pending_invitations(),
  public.accept_invitation(text, text), public.set_member_role(uuid, text), public.remove_member(uuid),
  public.consume_ai_message() to authenticated;
`;

function moduleSql(m: ModuleDef): string {
  const t = `public.${m.table}`;
  const cols = m.fields.map((f) => `  ${f.key} ${SQL_TYPE[f.type]}${f.required ? ' not null' : ''},`).join('\n');
  const own = m.ownRowsBelow ? ` and (public.user_rank() >= ${m.ownRowsBelow} or created_by = auth.uid())` : '';
  return `
-- ${m.label} (read ${m.read}, write ${m.write}, delete ${m.remove}${m.ownRowsBelow ? `, own rows below ${m.ownRowsBelow}` : ''})
create table ${t} (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null default public.user_company_id() references public.companies(id) on delete cascade,
  created_by uuid default auth.uid() references auth.users(id) on delete set null,
  title text not null check (char_length(title) between 1 and 300),
  status text not null,
  notes text,
${cols}
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index ${m.table}_company_idx on ${t}(company_id, created_at desc);
create trigger ${m.table}_updated before update on ${t} for each row execute function public.set_updated_at();
alter table ${t} enable row level security;
create policy ${m.table}_select on ${t} for select to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= ${m.read}${own});
create policy ${m.table}_insert on ${t} for insert to authenticated
  with check (company_id = public.user_company_id() and public.user_rank() >= ${m.write} and public.company_can_write() and created_by = auth.uid());
create policy ${m.table}_update on ${t} for update to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= ${m.write} and public.company_can_write()${own})
  with check (company_id = public.user_company_id());
create policy ${m.table}_delete on ${t} for delete to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= ${m.remove}${own});
revoke all on ${t} from anon;
grant select, insert, update, delete on ${t} to authenticated;
`;
}

export function generateMigration(): string {
  return CORE + '\n-- Module tables ---------------------------------------------------------------\n' + MODULES.map(moduleSql).join('');
}

if (import.meta.url === `file:///${process.argv[1]?.replace(/\\/g, '/')}` || process.argv[1]?.endsWith('generate-migration.ts')) {
  writeFileSync(MIGRATION_PATH, generateMigration());
  console.log(`Wrote ${MIGRATION_PATH} (${MODULES.length} module tables)`);
}
